formConfig.onFormMounted:
const now = new Date();
const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const visitDate = String(this.formDataModel?.visit_date || '').slice(0, 10);
if (visitDate !== today) return;

const current = this.formDataModel?.inscl_hos;
if (Array.isArray(current) && current.length > 0) return;
const personId = this.formDataModel?.pid?.value;
if (!personId) return;
await this.userState.runProcess('6a4c705049285083acfeb076', { personId }, (res) => {
  const rows = res?.data?.inscl_hos;
  if (Array.isArray(rows) && rows.length > 0) {
    this.setFormData({ inscl_hos: rows });
  }
});

